<script setup lang="ts">
import {ref,shallowRef,onMounted,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {message,Modal} from 'ant-design-vue';
import {listDatasets,listDatasetVersions,type Dataset,type DatasetVersion} from '@/api/evaluation';
import {listPipelines,listPipelineVersions,getPipeline} from '@/api/pipelines';
import type {PublishedPipeline,PipelineVersion} from '@/api/pipeline-policies';
import {usePermission} from '@/composables/permission';
import {listTasks,getTask,listTaskExecutions,type InspectionTask,type TaskExecutionSummary} from '@/api/tasks';
import {createEvaluationTask,getEvaluationReport,listEvaluationResults,getEvaluationResult,type EvaluationReport,type EvaluationResult} from '@/api/evaluation';
const {can}=usePermission(),route=useRoute(),router=useRouter();
const rows=ref<InspectionTask[]>([]),page=ref(1),total=ref(0),loading=ref(false),error=ref(''),busy=ref(false),createBusy=ref(false),createOpen=ref(false);
const form=ref({name:'',datasetId:'',datasetVersion:1,pipelineId:'',target:'published',targetVersion:1,concurrency:1});
const datasetOptions=ref<Dataset[]>([]),datasetVersions=ref<DatasetVersion[]>([]),datasetPage=ref(1),datasetTotal=ref(0),versionPage=ref(1),versionTotal=ref(0),pipelineOptions=ref<PublishedPipeline[]>([]),pipelineVersions=ref<PipelineVersion[]>([]),pipelinePage=ref(1),pipelineTotal=ref(0),pipelineDraft=ref<number>(),assetBusy=ref(false),assetError=ref('');let assetGeneration=0,datasetGeneration=0,pipelineGeneration=0;
const requestId=ref(''),selected=ref<InspectionTask>(),rounds=ref<TaskExecutionSummary[]>([]),executionId=ref<string>(),report=shallowRef<EvaluationReport>(),results=ref<EvaluationResult[]>([]),resultPage=ref(1),resultTotal=ref(0),detail=ref('');let generation=0,listGeneration=0,detailGeneration=0,resultGeneration=0;
const percent=(value:number|null|undefined)=>value==null?'无分母':`${(value*100).toFixed(2)}%`;
async function refresh(p=1){const ticket=++listGeneration;loading.value=true;error.value='';try{const d=await listTasks({taskType:'PIPELINE_EVALUATION',current:p,size:20});if(ticket===listGeneration){rows.value=d.records;total.value=d.total;page.value=p;}}catch{if(ticket===listGeneration)error.value='评测任务加载失败，请重试。';}finally{if(ticket===listGeneration)loading.value=false;}}
function openCreate(){++datasetGeneration;++pipelineGeneration;datasetVersions.value=[];pipelineVersions.value=[];pipelineDraft.value=undefined;versionTotal.value=0;assetError.value='';form.value={name:'',datasetId:typeof route.query.datasetId==='string'?route.query.datasetId:'',datasetVersion:1,pipelineId:'',target:'published',targetVersion:1,concurrency:1};requestId.value=crypto.randomUUID();createOpen.value=true;void loadAssets();if(form.value.datasetId)void chooseDataset(form.value.datasetId);}
async function loadAssets(){const ticket=++assetGeneration;assetBusy.value=true;assetError.value='';const done=await Promise.allSettled([listDatasets(datasetPage.value).then(d=>{if(ticket===assetGeneration){datasetOptions.value=d.records.filter(r=>r.status==='ACTIVE');datasetTotal.value=d.total;}}),listPipelines(pipelinePage.value).then(d=>{if(ticket===assetGeneration){pipelineOptions.value=d.records.filter(r=>r.status==='ACTIVE');pipelineTotal.value=d.total;}})]);if(ticket===assetGeneration){assetBusy.value=false;if(done.some(r=>r.status==='rejected'))assetError.value='资产目录加载失败，请检查目录权限后刷新。';}}
async function chooseDataset(id:string,p=1){form.value.datasetId=id;form.value.datasetVersion=0;datasetVersions.value=[];versionPage.value=p;const ticket=++datasetGeneration;try{const d=await listDatasetVersions(id,p);if(ticket===datasetGeneration){datasetVersions.value=d.records;versionTotal.value=d.total;form.value.datasetVersion=d.records[0]?.versionNo??0;}}catch{if(ticket===datasetGeneration)assetError.value='数据集冻结版本加载失败';}}
async function choosePipeline(id:string){form.value.pipelineId=id;pipelineVersions.value=[];pipelineDraft.value=undefined;form.value.targetVersion=0;const ticket=++pipelineGeneration;const done=await Promise.allSettled([listPipelineVersions(id).then(d=>{if(ticket===pipelineGeneration)pipelineVersions.value=d;}),getPipeline(id).then(d=>{if(ticket===pipelineGeneration)pipelineDraft.value=d.draftRevision;})]);if(ticket===pipelineGeneration){if(done.some(r=>r.status==='rejected'))assetError.value='目标版本或草稿加载失败，请核对读取权限。';updateTarget();}}
function updateTarget(){form.value.targetVersion=form.value.target==='draft'?(pipelineDraft.value??0):(pipelineVersions.value[0]?.versionNo??0);}
function closeCreate(){if(createBusy.value)return;Modal.confirm({title:'关闭创建窗口？',content:'当前填写的评测参数将被放弃。',onOk:()=>{createOpen.value=false;++assetGeneration;++datasetGeneration;++pipelineGeneration;}});}
watch(form,()=>{if(!createBusy.value)requestId.value=crypto.randomUUID();},{deep:true});
async function create(){if(createBusy.value||!form.value.datasetId.trim()||!form.value.pipelineId.trim()||!Number.isInteger(form.value.datasetVersion)||form.value.datasetVersion<1||!Number.isInteger(form.value.targetVersion)||form.value.targetVersion<1)return;createBusy.value=true;try{const f=form.value;const task=await createEvaluationTask({name:f.name.trim()||undefined,datasetId:f.datasetId.trim(),datasetVersion:f.datasetVersion,pipelineId:f.pipelineId.trim(),...(f.target==='published'?{pipelineVersion:f.targetVersion}:{draftRevision:f.targetVersion}),concurrency:f.concurrency,requestId:requestId.value});createOpen.value=false;message.success('评测任务已创建，请在任务页执行');await refresh();await router.replace({path:'/evaluation/tasks',query:{taskId:task.id}});}catch{message.error('创建未成功，请核对精确冻结版本、目标修订及权限；保留请求标识重试。');}finally{createBusy.value=false;}}
async function loadResults(p=1,ticket=generation){if(!selected.value||!executionId.value||!can('iqc:evaluation:results:view'))return;const request=++resultGeneration;const d=await listEvaluationResults(selected.value.id,executionId.value,p);if(ticket===generation&&request===resultGeneration){results.value=d.records;resultPage.value=p;resultTotal.value=d.total;}}
async function loadRound(){const ticket=++generation;++detailGeneration;report.value=undefined;results.value=[];resultTotal.value=0;detail.value='';busy.value=true;error.value='';try{const id=selected.value?.id;if(!id||!executionId.value){error.value='该评测任务尚未执行，请到任务页执行。';return;}const work:Promise<unknown>[]=[loadResults(1,ticket)];if(can('iqc:evaluation:report:view'))work.push(getEvaluationReport(id,executionId.value).then(d=>{if(ticket===generation)report.value=d;}));const done=await Promise.allSettled(work);if(ticket===generation&&done.some(r=>r.status==='rejected'))error.value='部分评测数据加载失败，请刷新；未执行任务还没有报告。';}finally{if(ticket===generation)busy.value=false;}}
async function selectTask(id:string){const ticket=++generation;busy.value=true;error.value='';report.value=undefined;results.value=[];detail.value='';selected.value=undefined;rounds.value=[];try{const [task,history]=await Promise.all([getTask(id),listTaskExecutions(id)]);if(ticket!==generation)return;if(task.taskType!=='PIPELINE_EVALUATION')throw Error();selected.value=task;rounds.value=history;executionId.value=task.currentExecutionId||history[0]?.id;await loadRound();}catch{if(ticket===generation){error.value='任务加载失败，或该任务不是评测任务。';busy.value=false;}}}
async function viewResult(row:EvaluationResult){if(!selected.value)return;const ticket=++detailGeneration,id=selected.value.id;try{const d=await getEvaluationResult(id,row.id);if(ticket===detailGeneration&&selected.value?.id===id)detail.value=JSON.stringify({...d,actual:d.actualJson?JSON.parse(d.actualJson):null,actualJson:undefined},null,2);}catch{message.error('评测产物加载失败');}}
function showTask(id:string){void router.replace({path:'/evaluation/tasks',query:{taskId:id}});}
watch(()=>route.query.taskId,id=>{if(typeof id==='string')void selectTask(id);else{++generation;++detailGeneration;++resultGeneration;selected.value=undefined;report.value=undefined;results.value=[];rounds.value=[];detail.value='';busy.value=false;}});
onMounted(()=>{void refresh();if(typeof route.query.taskId==='string')void selectTask(route.query.taskId);});
</script>
<template>
<section class="page-intro"><div><h2>固定数据集评测</h2><p>完整冻结金标进入分母。报告完整表示终态且产物齐全；发布门禁尚未接入。</p></div><a-button v-if="can('iqc:evaluation:task:create')" type="primary" @click="openCreate">创建评测任务</a-button></section>
<a-alert v-if="error" type="warning" :message="error"/><a-button :loading="loading" @click="refresh(page)">刷新任务</a-button><a-button @click="router.push('/tasks')">任务执行与暂停</a-button>
<a-table :data-source="rows" row-key="id" :pagination="false" :loading="loading"><a-table-column title="名称" data-index="name"/><a-table-column title="状态" data-index="status"/><a-table-column title="操作"><template #default="{record}"><a-button @click="showTask(record.id)">评测结果 / 报告</a-button></template></a-table-column></a-table><a-pagination :current="page" :total="total" :page-size="20" :show-size-changer="false" @change="refresh"/>
<a-modal :open="createOpen" title="创建固定数据集评测" :confirm-loading="createBusy" :mask-closable="false" :keyboard="false" @ok="create" @cancel="closeCreate"><a-alert v-if="assetError" type="warning" :message="assetError"/><a-button :loading="assetBusy" @click="loadAssets">刷新可用资产目录</a-button><a-form layout="vertical" :disabled="createBusy"><a-form-item label="名称"><a-input v-model:value="form.name" :maxlength="128"/></a-form-item><a-form-item label="数据集 ID"><a-select :value="form.datasetId||undefined" show-search option-filter-prop="label" :options="datasetOptions.map(d=>({value:d.id,label:`${d.name} · ${d.id}`}))" @change="(id:string)=>chooseDataset(id)"/><a-pagination v-model:current="datasetPage" :total="datasetTotal" :page-size="20" :show-size-changer="false" @change="loadAssets"/></a-form-item><a-form-item label="精确冻结数据集版本"><a-select v-model:value="form.datasetVersion" :options="datasetVersions.map(d=>({value:d.versionNo,label:`v${d.versionNo} · ${d.sampleCount} 样本 · 修订 ${d.sourceDraftRevision}`}))"/><a-pagination :current="versionPage" :total="versionTotal" :page-size="20" :show-size-changer="false" @change="(p:number)=>chooseDataset(form.datasetId,p)"/></a-form-item><a-button @click="router.push('/evaluation/datasets')">查看数据集目录</a-button><a-form-item label="Pipeline ID"><a-select :value="form.pipelineId||undefined" show-search option-filter-prop="label" :options="pipelineOptions.map(d=>({value:d.id,label:`${d.name} · ${d.code}`}))" @change="choosePipeline"/><a-pagination v-model:current="pipelinePage" :total="pipelineTotal" :page-size="20" :show-size-changer="false" @change="loadAssets"/></a-form-item><a-form-item label="目标类型"><a-radio-group v-model:value="form.target" @change="updateTarget"><a-radio value="published">发布版本</a-radio><a-radio value="draft">精确草稿修订</a-radio></a-radio-group></a-form-item><a-form-item :label="form.target==='published'?'精确发布版本':'精确草稿修订'"><a-select v-if="form.target==='published'" v-model:value="form.targetVersion" :options="pipelineVersions.map(d=>({value:d.versionNo,label:`v${d.versionNo} · 修订 ${d.sourceDraftRevision}`}))"/><span v-else>当前已保存修订 {{pipelineDraft??'未加载'}}，创建时由服务端校验精确修订。</span></a-form-item><a-form-item label="并发会话"><a-input-number v-model:value="form.concurrency" :min="1" :max="32" :precision="0"/></a-form-item></a-form><p>创建后手动执行；修改参数将生成新的请求标识，失败后原参数重试沿用原标识。</p></a-modal>
<template v-if="selected"><h3>{{selected.name}} · {{selected.status}}</h3><a-space><a-select v-model:value="executionId" :options="rounds.map(r=>({value:r.id,label:`第 ${r.attemptNo} 轮 · ${r.status} · ${r.id}`}))" style="width:500px" :disabled="busy" @change="loadRound"/><a-button :loading="busy" @click="selectTask(selected.id)">刷新当前执行</a-button></a-space>
<template v-if="report"><a-alert :type="report.complete?'info':'warning'" :message="report.complete?'报告产物齐全（不代表质检达标或发布获准）':'报告不完整：缺失样本仍进入指标分母'"/><a-descriptions bordered :column="3"><a-descriptions-item label="冻结金标样本">{{report.expectedSamples}}</a-descriptions-item><a-descriptions-item label="已有产物">{{report.availableSamples}}</a-descriptions-item><a-descriptions-item label="执行成功">{{report.successfulSamples}}</a-descriptions-item><a-descriptions-item label="精确率">{{percent(report.findingMetrics.aggregate.precision)}}</a-descriptions-item><a-descriptions-item label="召回率">{{percent(report.findingMetrics.aggregate.recall)}}</a-descriptions-item><a-descriptions-item label="F1">{{percent(report.findingMetrics.aggregate.f1)}}</a-descriptions-item><a-descriptions-item label="事实覆盖率">{{percent(report.findingMetrics.aggregate.coverage)}}</a-descriptions-item><a-descriptions-item label="值准确率">{{percent(report.findingMetrics.aggregate.valueAccuracy)}}</a-descriptions-item><a-descriptions-item label="证据准确率">{{percent(report.findingMetrics.aggregate.evidenceAccuracy)}}</a-descriptions-item><a-descriptions-item label="分数 MAE">{{report.businessMetrics.meanAbsoluteScoreError??'无可比样本'}}</a-descriptions-item><a-descriptions-item label="分数覆盖率">{{percent(report.businessMetrics.scoreCoverage)}}</a-descriptions-item><a-descriptions-item label="高风险召回">{{percent(report.businessMetrics.highRiskRecall)}}</a-descriptions-item><a-descriptions-item label="标签准确率">{{percent(report.businessMetrics.labelAccuracy)}}（标签输出未接入）</a-descriptions-item><a-descriptions-item label="P50/P95/P99 毫秒">{{report.latencyMetrics.p50Ms??'—'}} / {{report.latencyMetrics.p95Ms??'—'}} / {{report.latencyMetrics.p99Ms??'—'}}</a-descriptions-item><a-descriptions-item label="已有产物执行失败率">{{percent(report.latencyMetrics.executionFailureRate)}}</a-descriptions-item><a-descriptions-item v-if="report.regressionMetrics" label="回归通过率">{{percent(report.regressionMetrics.passRate)}} · {{report.regressionMetrics.passedSamples}} / {{report.regressionMetrics.expectedSamples}}</a-descriptions-item></a-descriptions>
<p>耗时仅包含会话评测计算，排除排队、准备和落库；失败率不含缺失产物。报告继承较早重试轮次的样本，下面列表仅显示选中执行轮次。</p><details><summary>按事实指标、计数、缺失样本及原执行来源</summary><pre>{{JSON.stringify(report,null,2)}}</pre></details></template>
<h3>当前执行轮次样本产物</h3><a-table :data-source="results" row-key="id" :pagination="false"><a-table-column title="样本" data-index="sampleId"/><a-table-column title="金标版本" data-index="sampleVersion"/><a-table-column title="状态" data-index="status"/><a-table-column title="耗时 ms" data-index="durationMs"/><a-table-column title="操作"><template #default="{record}"><a-button v-if="can('iqc:evaluation:result:view')" @click="viewResult(record)">实际轨迹 / 来源</a-button></template></a-table-column></a-table><a-pagination :current="resultPage" :total="resultTotal" :page-size="20" :show-size-changer="false" @change="(p:number)=>loadResults(p).catch(()=>message.error('产物分页加载失败'))"/><pre v-if="detail">{{detail}}</pre>
</template>
</template>
<style scoped>.ant-alert,.ant-space,.ant-pagination{margin:12px 0}pre{max-height:600px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}</style>
